// HouseWatch FB: посты из групп аренды Facebook (их шлёт сборщик housewatch/fb-collector с Mac).
// Грубый отсев регулярками → один запрос к GPT на выживших → FB Format решает и шлёт в Telegram.
// Все настройки — здесь.
const cfg = {
  MAX_RENT_VND: 10000000, // потолок аренды; коммуналка сверху (13.11: «до 10 млн, мне ещё за коммуналку платить»)
  MIN_RENT_VND: 3000000,  // ниже — комнаты/мусор
  UTIL_VND: 2500000,      // оценка света и воды, для «под ключ» в ₽
  MIN_BEDROOMS: 2,
  MAX_ALERTS: 10,         // постов в Telegram за прогон
  LLM_MAX: 40,            // постов в GPT за прогон
  DEDUP_DAYS: 30,         // один и тот же текст агенты постят в 5 групп и повторяют — шлём один раз
  LLM_MODEL: 'gpt-5-mini',
  CHATS: ['648226895', '893232025'], // как в HouseWatch_VN
};
const v = $('CBR Rate').first().json?.Valute?.VND;
const vndPerRub = v && v.Value ? v.Nominal / v.Value : 312;
const body = $('FB Webhook').first().json.body || {};

if (body.type === 'login_required') {
  return [{ json: { cfg, vndPerRub, service: true, text: '⚠️ <b>HouseWatch FB</b>: Facebook просит заново войти. На Mac: <code>cd housewatch/fb-collector &amp;&amp; node collect.mjs --login</code>' } }];
}
const posts = Array.isArray(body.posts) ? body.posts : [];

// --- цена из текста, млн ₫ (первое упоминание суммы аренды) ---
function priceVnd(t) {
  const s = t.replace(/(\d),(\d{3})/g, '$1.$2');
  let m = s.match(/(\d{1,3}(?:[.,]\d{1,2})?)\s*(?:tr\b|tr\/|triệu|trieu|млн|миллион|million|mil\b|m\s*\/\s*(?:th|month))/i);
  if (m) return Math.round(parseFloat(m[1].replace(',', '.')) * 1e6);
  m = s.match(/(\d{1,3})[.\s](\d{3})[.\s](\d{3})\s*(?:đ|₫|vnđ|vnd|донг)?/i);
  if (m) return Number(m[1] + m[2] + m[3]);
  m = s.match(/#\s*(\d{1,2})\s*tri/i);
  if (m) return Number(m[1]) * 1e6;
  return null;
}
const TWO = /\b([2-9])\s*(pn|phòng ngủ|phong ngu|bedrooms?|br\b|спальн|-?комнатн)|\b[2-9]PN\b|[2-9]-BEDROOM/i;
const ONE = /\b1\s*(pn|phòng ngủ|phong ngu|bedroom|спальн)|\bstudio\b|студи/i;
const RULES = [
  ['продажа', t => /(bán nhà|bán căn|bán đất|cần bán|giá bán|продаю|продаётся|продается|for sale)/i.test(t) && !/cho thuê|for rent|аренд/i.test(t)],
  ['ищут жильё', t => /^\s*(cần thuê|cần tìm|tìm nhà|tìm căn|ищу|ищем|looking for|need)(?![\p{L}])/iu.test(t)],
  ['1 спальня / студия', t => ONE.test(t) && !TWO.test(t)],
  ['только вьетнамцам', t => /(chỉ|chi)\s*(cho\s*)?(nhận\s*)?khách\s*(việt|viet)|nhận khách việt|khách việt nam|only vietnamese|только (для )?вьетнам/i.test(t)],
  ['оплата раз в 2+ мес', t => /(thanh toán|thanh toan|(?<!\p{L})tt|đóng|trả)\s*([2-9]|1[0-2])(?!\d)/iu.test(t) || /(pay|payment)\s*(every\s*)?[2-9]\s*months?|[2-9]\s*months?\s*(prepay|in advance|payment)|оплат\w*\s*(за|раз в|каждые)\s*[2-9]/i.test(t)],
];
const sd = $getWorkflowStaticData('global');
sd.texts = sd.texts || {};
const now = Date.now();
for (const [k, t] of Object.entries(sd.texts)) if (now - t > cfg.DEDUP_DAYS * 86400e3) delete sd.texts[k];
const norm = t => t.toLowerCase().replace(/[^\p{L}\p{N}]/gu, '').slice(0, 160);

const stats = { in: posts.length, dup: 0 };
const keep = [];
for (const p of posts) {
  const t = String(p.text || '');
  if (t.length < 30) continue;
  const key = norm(t);
  if (sd.texts[key]) { stats.dup++; continue; }
  const why = (RULES.find(([, f]) => f(t)) || [])[0];
  const price = priceVnd(t);
  const reason = why || (price != null && price > cfg.MAX_RENT_VND * 1.05 ? 'дороже лимита'
    : price != null && price < cfg.MIN_RENT_VND ? 'слишком дёшево (комната?)' : null);
  if (reason) { stats[reason] = (stats[reason] || 0) + 1; sd.texts[key] = now; continue; }
  // Цены нет и про 2 спальни ни слова — вероятно мусор, но обрезанные посты даём GPT.
  if (price == null && !TWO.test(t) && !p.truncated) { stats['нет цены и спален'] = (stats['нет цены и спален'] || 0) + 1; sd.texts[key] = now; continue; }
  sd.texts[key] = now; // сразу: дубли внутри одной пачки тоже склеиваются
  keep.push({ ...p, price_guess: price });
}
const batch = keep.slice(0, cfg.LLM_MAX);
// Хвост сверх LLM_MAX теряется (сборщик пост повторно не пришлёт) — при 6 группах раз в 1,5 ч столько не набирается.
if (!batch.length) return [];

const N = t => ({ type: [t, 'null'] });
const request = {
  model: cfg.LLM_MODEL,
  reasoning_effort: 'low',
  response_format: { type: 'json_schema', json_schema: { name: 'fbposts', strict: true, schema: {
    type: 'object', additionalProperties: false, required: ['items'],
    properties: { items: { type: 'array', items: { type: 'object', additionalProperties: false,
      required: ['id', 'is_rent_offer', 'rent_vnd', 'bedrooms', 'foreigners_ok', 'deposit_months', 'pay_every_months', 'min_term_months', 'kind', 'place', 'contacts', 'summary_ru'],
      properties: {
        id: { type: 'string' }, is_rent_offer: { type: 'boolean' }, rent_vnd: N('number'), bedrooms: N('number'),
        foreigners_ok: N('boolean'), deposit_months: N('number'), pay_every_months: N('number'), min_term_months: N('number'),
        kind: { type: ['string', 'null'], enum: ['apartment', 'house', 'room', 'other', null] },
        place: { type: 'string' }, contacts: { type: 'string' }, summary_ru: { type: 'string' } } } } },
  } } },
  messages: [
    { role: 'system', content:
      'Ты читаешь посты из групп аренды жилья в Нячанге (Вьетнам) — по-вьетнамски, по-английски или по-русски, часто с опечатками. ' +
      'Семья (2 взрослых + ребёнок) снимает на несколько месяцев, платит только помесячно, нужна аренда целиком на 2+ спальни. ' +
      'Для каждого поста верни поля по его id. Ничего не выдумывай: нет в тексте — null.\n' +
      '- is_rent_offer: true, если это предложение сдать жильё в аренду целиком на месяцы (не продажа, не поиск жилья, не посуточно-только, не комната/койка).\n' +
      '- rent_vnd: месячная аренда в донгах для долгого срока (если цен несколько — за самый длинный срок; «10tr» = 10000000). Отдельная цена для иностранцев — бери её.\n' +
      '- bedrooms: число спален («2PN», «2 phòng ngủ», «2-комнатная» = 2; «1PN+1» = 1).\n' +
      '- foreigners_ok: false, если сдают только вьетнамцам (chỉ khách Việt); true, если явно рады иностранцам; иначе null.\n' +
      '- deposit_months: залог (cọc) в месяцах. pay_every_months: раз во сколько месяцев платить («cọc 1 thanh toán 1» = 1, «cọc 2 tt 3» = 3). ' +
      'min_term_months: минимальный срок договора (HĐ 1 năm = 12, «3-6-12 tháng» = 3).\n' +
      '- kind: apartment (căn hộ, chung cư), house (nhà nguyên căn), room (phòng trọ, комната), other.\n' +
      '- place: ЖК / улица / район коротко латиницей как в тексте (пример: «Hoàng Quân, Bắc Nha Trang»), иначе пустая строка.\n' +
      '- contacts: телефоны/Zalo/WhatsApp/Telegram из текста через запятую, иначе пустая строка.\n' +
      '- summary_ru: до 140 символов по-русски — полезное для семьи (площадь, мебель, до моря, этаж/лифт, питомцы, свет по госцене, бассейн). Без цены и контактов.' },
    { role: 'user', content: JSON.stringify(batch.map(p => ({ id: p.id, text: String(p.text).slice(0, 1800) }))) },
  ],
};
return [{ json: { cfg, vndPerRub, stats, posts: batch, request } }];

// Решение по каждому посту по ответу GPT и карточки в Telegram.
// GPT не ответил — шлём то, что прошло регулярки, с куском текста (лучше лишнее, чем пропустить).
const f = $('FB Filter').first().json;
const { cfg, vndPerRub } = f;
if (f.service) return cfg.CHATS.map(chat_id => ({ json: { chat_id, text: f.text } }));

const G = {};
let llmOk = false;
try {
  for (const t of JSON.parse($input.first().json.choices[0].message.content).items) G[t.id] = t;
  llmOk = true;
} catch (e) { /* фолбэк */ }

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mln = n => String(Math.round(n / 1e5) / 10).replace('.', ',');
const mo = n => (n == null ? '—' : `${String(n).replace('.', ',')} мес`);
const pay = n => (n == null ? 'не указана' : n === 1 ? 'помесячно ✅' : `раз в ${mo(n)}`);
const KIND = { apartment: 'квартира', house: 'дом', room: 'комната', other: '' };

const out = [];
const skipped = {};
const skip = r => { skipped[r] = (skipped[r] || 0) + 1; };
for (const p of f.posts) {
  const g = G[p.id];
  const rent = g?.rent_vnd ?? p.price_guess;
  if (g) {
    if (!g.is_rent_offer) { skip('не аренда'); continue; }
    if (g.kind === 'room') { skip('комната'); continue; }
    if (g.bedrooms != null && g.bedrooms < cfg.MIN_BEDROOMS) { skip('мало спален'); continue; }
    if (g.foreigners_ok === false) { skip('только вьетнамцам'); continue; }
    if (g.pay_every_months != null && g.pay_every_months > 1) { skip('оплата не помесячно'); continue; }
    if (rent != null && rent > cfg.MAX_RENT_VND) { skip('дороже лимита'); continue; }
  }
  const warn = [];
  if (rent == null) warn.push('цена не указана');
  if (g && g.bedrooms == null) warn.push('спальни не указаны');
  if (g && g.pay_every_months == null) warn.push('оплату уточнить (нужно помесячно)');
  if (g && g.min_term_months >= 12) warn.push('договор от года — спросить про 3–6 мес');
  const rub = rent != null ? Math.round((rent + cfg.UTIL_VND) / vndPerRub / 1000) : null;
  const head = g ? [KIND[g.kind], g.bedrooms ? `${g.bedrooms} спальни` : '', g.place].filter(Boolean).join(' · ') : '';
  const text =
    `🏠 <b>FB · Нячанг</b>${head ? ' — ' + esc(head) : ''}\n` +
    (rent != null ? `💰 ${mln(rent)} млн ₫ · под ключ ≈ ${rub} тыс. ₽\n` : '') +
    (g ? `🔐 Залог: ${mo(g.deposit_months)} · оплата: ${pay(g.pay_every_months)} · договор: ${g.min_term_months == null ? 'не указан' : 'от ' + mo(g.min_term_months)}\n` : '') +
    (g?.summary_ru ? `📝 ${esc(g.summary_ru)}\n` : '') +
    (g?.contacts ? `📞 ${esc(g.contacts)}\n` : '') +
    (!g ? `📝 ${esc(String(p.text).slice(0, 400))}${String(p.text).length > 400 ? '…' : ''}\n` : '') +
    (warn.length ? `⚠️ ${warn.join(' · ')}\n` : '') +
    `<a href="${esc(p.link)}">Пост в группе «${esc(p.groupName || p.group)}»</a>`;
  out.push({ rent: rent ?? 1e12, text });
}
const send = out.sort((a, b) => a.rent - b.rent).slice(0, cfg.MAX_ALERTS);
if (!llmOk && send.length) send.push({ text: '(HouseWatch FB: GPT не ответил — посты выше прошли только регулярки, условия не разобраны)' });
return send.flatMap(o => cfg.CHATS.map(chat_id => ({ json: { chat_id, text: o.text } })));

// Уведомление о падении воркфлоу. Троттлинг на ноду — 30 мин (как во FlightWatch).
const QUIET_MS = 30 * 60 * 1000;
const e = $json.execution || {};
const err = e.error || {};
const wf = $json.workflow || {};
const node = e.lastNodeExecuted || '?';
const s = $getWorkflowStaticData('global');
if (!s.errAlerts) s.errAlerts = {};
const st = s.errAlerts[node] || { last: 0, suppressed: 0 };
const now = Date.now();
if (now - st.last < QUIET_MS) { st.suppressed += 1; s.errAlerts[node] = st; return []; }
const repeats = st.suppressed;
s.errAlerts[node] = { last: now, suppressed: 0 };
const text =
  `⚠️ HouseWatch VN упал\nВоркфлоу: ${wf.name || '?'}\nНода: ${node}\n` +
  `Ошибка: ${err.message || 'без текста'}` +
  (repeats ? `\n(за последние 30 мин ещё ${repeats} таких, они скрыты)` : '') +
  (e.url ? `\n${e.url}` : '');
return [{ json: { chat_id: '648226895', text } }];
